105	/**
106	 * Helper function that gets currency data from a stored JSON file
107	 * Uses public data from European Central Bank
108	 */
109	function _getCurrencyData (callback) {
110	  const data = require('./data/currency_conversion.json');
111	  callback(data);
112	}
113	
114	/**
115	 * Helper function that handles decimal/fractional carrying
116	 */
117	function _carry (amount) {
118	  const fractionSize = Math.pow(10, 9);
119	  amount.nanos += (amount.units % 1) * fractionSize;
120	  amount.units = Math.floor(amount.units) + Math.floor(amount.nanos / fractionSize);
121	  amount.nanos = amount.nanos % fractionSize;
122	  return amount;
123	}
