   135	/**
   136	 * Converts between currencies
   137	 */
   138	function convert (call, callback) {
   139	  try {
   140	    _getCurrencyData((data) => {
   141	      const request = call.request;
   142	
   143	      // Convert: from_currency --> EUR
   144	      const from = request.from;
   145	      const euros = _carry({
   146	        units: from.units / data[from.currency_code],
   147	        nanos: from.nanos / data[from.currency_code]
   148	      });
   149	
   150	      euros.nanos = Math.round(euros.nanos);
   151	
   152	      // Convert: EUR --> to_currency
   153	      const result = _carry({
   154	        units: euros.units * data[request.to_code],
   155	        nanos: euros.nanos * data[request.to_code]
   156	      });
   157	
   158	      result.units = Math.floor(result.units);
   159	      result.nanos = Math.floor(result.nanos);
   160	      result.currency_code = request.to_code;
   161	
   162	      logger.info(`conversion request successful`);
   163	      callback(null, result);
   164	    });
